  ('higher-math-board-dhaka-2023-mcq-018', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p38', 'A (-1,2), B(2,5) এবং C(1,3) শীর্ষবিশিষ্ট ABC ত্রিভুজের ক্ষেত্রফল নিচের কোনটি?', 'mcq', '{"ক":"25","খ":"25 2","গ":"3","ঘ":"3 2"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-dhaka-2023-mcq', false, 'board-mcq', null, null, 'dhaka', 2023, true),
