  ('higher-math-board-dhaka-2024-mcq-003', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'যদি 2y+1 y(y−1) = A y + B y−1 হয় তবে A এর মান কত?', 'mcq', '{"ক":"-1","খ":"1","গ":"2","ঘ":"3"}'::jsonb, 'ক', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-004', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'একটি সমবাহু ত্রিভুজের প্রতিটি মধ্যমার দৈর্ঘ্য 6cm হলে ঐ ত্রিভুজের প্রতিটি বাহুর দৈর্ঘ্য কত সে. মিটার?', 'mcq', '{"ক":"6√2","খ":"6","গ":"4√3","ঘ":"3√3"}'::jsonb, 'গ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-005', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'নব বিন্দু বৃত্তের ব্যাসার্ধ 7 সে.মি. হলে পরিবৃত্তের ক্ষেত্রফল কত বর্গ সে.মি.?', 'mcq', '{"ক":"7π","খ":"14π","গ":"49π","ঘ":"196π"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-006', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'একটি ত্রিভুজের পরিকেন্দ্র, ভরকেন্দ্র ও সম্ববিন্দু যোগ করলে কোনটি গঠিত হয়?', 'mcq', '{"ক":"সরল রেখা","খ":"বৃত্ত","গ":"ত্রিভুজ","ঘ":"কোণক"}'::jsonb, 'ক', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-007', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', '2 + 5x - 4x2 = 0 সমীকরণের মূলগুলোর প্রকৃতি কেমন?', 'mcq', '{"ক":"মূলদ","খ":"অমূলদ","গ":"সমান","ঘ":"জটিল"}'::jsonb, 'খ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-008', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'কোনো একটি অনুক্রমের তম পদ Un = 1 + (-1)n+1 হলে, এর i. ১তম পদ 2 ii. 12তম পদ 12 iii. প্রথম 10টি পদের সমষ্টি 10 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-009', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p15', 'F (x) = 2 ফাংশনটির ডোমেন কত? 2x−1', 'mcq', '{"ক":"{x ∈ R : x ≠ − 1 }","খ":"{x ∈ R : x ≠ 1 }","গ":"{x ∈ R : x ≥ 1 }","ঘ":"{x ∈ R : x > 1 } 2 2 2 2"}'::jsonb, 'খ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-010', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p16', 'P(-3, 2) এবং Q (3, -2) দুইটি বিন্দু হলে- i. PQ এর দৈর্ঘ্য একক 2√13 ii. PQ, x অক্ষের ধনাত্মক দিকের সাথে স্থূলকোণ উৎপন্ন করে ili. PQ এর ঢাল 2 3 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-011', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p16', 'P ও Q বিন্দুর অবস্থান ভেক্টর যথাক্রমে 5 a − 3 b এবং 2 a − b হলে − −⇀ PQ = কত?', 'mcq', '{"ক":"3 a − 2 b","খ":"−3 a + 2 b","গ":"7 a − 4 b","ঘ":"7 a + 4 b"}'::jsonb, 'খ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-012', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p16', 'সমান উচ্চতাবিশিষ্ট একটি সিলিন্ডার ও একটি সমবৃত্তভূমিক কোণকের ভূমি সমান হলে তাদের আয়তনের অনুপাত কোনটি?', 'mcq', '{"ক":"1:2","খ":"1:3","গ":"2:1","ঘ":"3:1"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-013', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p16', 'পাঁচ টাকার পাঁচটি মুদ্রা এক সাথে নিক্ষেপ করা হলে, নমুনা বিন্দু কয়টি হবে?', 'mcq', '{"ক":"5","খ":"25","গ":"32","ঘ":"64"}'::jsonb, 'গ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', null, null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-014', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p16', 'A = {x: r ∈ N, x2 + 9x + 20 = 0} হলে n(A) = কত?', 'mcq', '{"ক":"4","খ":"2","গ":"1","ঘ":""}'::jsonb, 'ঘ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', 'অপশন চিহ্ন পাওয়া যায়নি: ঘ (ছাপায় নেই বা চিত্র আকারে); ঘ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'dhaka', 2024, true),
  ('higher-math-board-dhaka-2024-mcq-015', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p16', 'x − 4 ≤ x 3 এর সমাধান সংখ্যারেখায় কোনটি?', 'mcq', '{"ক":"","খ":"","গ":"","ঘ":""}'::jsonb, 'গ', 1, false, 'higher-math-board-dhaka-2024-mcq', false, 'board-mcq', 'অপশন চিহ্ন (a/b/c/d) টেক্সটে পাওয়া যায়নি (সম্ভবত চিত্র আকারে); ক অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); খ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); গ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); ঘ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'dhaka', 2024, true),
