  ('higher-math-board-jessore-2024-mcq-024', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p11', 'i. সরলরেখাটির ঢাল 1 2 ii. x-অক্ষের ধনাত্মক দিকের সহিত সরলরেখাটি স্থূলকোণ উৎপন্ন করে iii. সরলরেখাটির y-অক্ষের ছেদাংশ 11 একক নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'higher-math-board-jessore-2024-mcq', false, 'board-mcq', null, '2x + y = 11 একটি সরলরেখার সমীকরণ।', 'jessore', 2024, true),
  ('higher-math-board-jessore-2024-mcq-025', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p11', 'সরলরেখাটির উপর P(a, 3) বিন্দুটি অবস্থিত হলে, মূলবিন্দু হতে P বিন্দুর দূরত্ব কত একক?', 'mcq', '{"ক":"11","খ":"5","গ":"4","ঘ":"3"}'::jsonb, 'খ', 1, false, 'higher-math-board-jessore-2024-mcq', false, 'board-mcq', null, '2x + y = 11 একটি সরলরেখার সমীকরণ।', 'jessore', 2024, true),
  ('higher-math-board-mymensingh-2023-mcq-001', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'রেখাটি x-অক্ষের ধনাত্মক দিকের সাথে কত কোণ উৎপন্ন করে?', 'mcq', '{"ক":"30°","খ":"45°","গ":"90°","ঘ":"135°"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-002', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'A বিন্দুর স্থানাংক কত?', 'mcq', '{"ক":"(0,3)","খ":"(0, − 3 )","গ":"(-3,0)","ঘ":"(3,0)"}'::jsonb, 'ক', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-003', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'সজীবের রওনা হওয়ার সময় ঘড়ির ঘণ্টার কাঁটা ও মিনিটের কাঁটার অন্তর্গত কোণ কত হবে?', 'mcq', '{"ক":"π 4 রেডিয়ান","খ":"π 3 রেডিয়ান","গ":"7π রেডিয়ান","ঘ":"5π 12 রেডিয়ান 12"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, 'সজীব সকাল 7:30 টায় বিদ্যালয়ের উদ্দেশ্যে রওনা হয়ে সকাল 7 : 45 টায় বিদ্যালয়ে পৌঁছায়। তার ঘড়ির মিনিটের কাঁটার দৈর্ঘ্য 4 মি.মি.।', 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-004', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'বাড়ি থেকে বিদ্যালয় পর্যন্ত পৌছাতে মিনিটের কাঁটাটির অগ্রভাগ কত দূরত্ব অতিক্রম করে?', 'mcq', '{"ক":"π মি.মি","খ":"3π মি.মি 2","গ":"2π মি.মি","ঘ":"5π মি.মি 2"}'::jsonb, 'গ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, 'সজীব সকাল 7:30 টায় বিদ্যালয়ের উদ্দেশ্যে রওনা হয়ে সকাল 7 : 45 টায় বিদ্যালয়ে পৌঁছায়। তার ঘড়ির মিনিটের কাঁটার দৈর্ঘ্য 4 মি.মি.।', 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-005', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', '(x + 1 ) n এর বিস্তৃতিতে দ্বিতীয় পদের সহগ তৃতীয় পদের সহগের সমান হলে, n এর মান কত? x', 'mcq', '{"ক":"2","খ":"3","গ":"4","ঘ":"5"}'::jsonb, 'খ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-007', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', '16 − 4 + 1 − 1 + ............ গুণোত্তর ধারাটির অসীমতক সমষ্টি কত? 4', 'mcq', '{"ক":"12","খ":"64 5","গ":"20","ঘ":"64 3"}'::jsonb, 'খ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-008', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'একটি বাক্সে 6 টি নীল, 5 টি সবুজ ও 7 টি হলুদ বল আছে। বাক্সটি থেকে নিরপেক্ষভাবে একটি বল তোলা হলে তা সাদা হওয়ার সম্ভাবনা কত?', 'mcq', '{"ক":"7 18","খ":"6 18","গ":"5 18","ঘ":"0 18"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-009', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'একটি সমবাহু ত্রিভুজের বাহুর দৈর্ঘ্য 9 সে.মি. হলে ঐ ত্রিভুজের পরিবৃত্তের ব্যাস কত?', 'mcq', '{"ক":"3 সে.মি.","খ":"3√3 সে.মি.","গ":"6√3 সে.মি.","ঘ":"9√3 সে.মি."}'::jsonb, 'গ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-010', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'দুইটি ছক্কা ও একটি মুদ্রা একত্রে একবার নিক্ষেপ করলে সংঘটিত ঘটনার নমুনা বিন্দুর সংখ্যা কত হবে?', 'mcq', '{"ক":"144","খ":"72","গ":"36","ঘ":"24"}'::jsonb, 'খ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-011', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', '1+3+9+27+………. ধারাটির— i. সাধারণ অনুপাত 3 ii. n তম পদ 3 n- 1 iii. প্রথম 7 টি পদের সমষ্টি 1093 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-013', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'sin β = 1 2 হলে cos 3β − sin 3β এর মান কত?', 'mcq', '{"ক":"-2","খ":"-1","গ":"1","ঘ":"2"}'::jsonb, 'খ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-014', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p25', 'দুইটি বহুপদী F(x) ও G(x) সকল x এর জন্য সমান হলে-- i.এদের সমতাকে অভেদ বলা হয় ii. বহুপদীদ্বয়কে F(x) = G(x) আকারে লেখা যায় iii. উভয়ের মাত্রা অসমান হয় নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-015', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', '∫ (x) = 1 − 4 −x এর বিপরীত ফাংশন নিচের কোনটি?', 'mcq', '{"ক":"log 4 (x − 1)","খ":"log 4 (1 − x)","গ":"log ( 1 )","ঘ":"log ( 1 ) 4 1−x 4 x−1"}'::jsonb, 'গ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-016', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', '∫ (x) = I n (x – 2 ) ফাংশনটি— i. একটি লগারিদমিক ফাংশন ii. x > 2 এর জন্য সংজ্ঞায়িত iii. রেঞ্জ R ∫ = (0, ∞) নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-018', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', 'একটি ত্রিভুজের নববিন্দু বৃত্তের পরিধি 2 সে.মি. হলে ঐ ত্রিভুজের পরিবৃত্তের ক্ষেত্রফল কত?', 'mcq', '{"ক":"2π বর্গ সে.মি.","খ":"4π বর্গ সে.মি.","গ":"8π বর্গ সে.মি.","ঘ":"16π বর্গ সে.মি"}'::jsonb, 'খ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-019', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', '(9x - 6x + x2)3n এর বিসতৃত পদসংখ্যা 7 হলে, n এর মান কত?', 'mcq', '{"ক":"1","খ":"2","গ":"4","ঘ":"6"}'::jsonb, 'ক', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
  ('higher-math-board-mymensingh-2023-mcq-020', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', 'একটি নিরপেক্ষ ছক্কা একবার নিক্ষেপ করা হলে প্রাপ্ত সংখ্যাটি জোড় কিন্তু 6 দ্বারা বিভাজ্য না হওয়ার সম্ভাবনা কত হবে?', 'mcq', '{"ক":"1 6","খ":"1 3","গ":"2 3","ঘ":"5 6"}'::jsonb, 'খ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
