  ('higher-math-board-mymensingh-2023-mcq-023', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', '1−x = 2 + B হলে, B এর মান কত হবে? (x + 3) (x + 5) (x + 3) (x + 5)', 'mcq', '{"ক":"-3","খ":"-2","গ":"2","ঘ":"4"}'::jsonb, 'ক', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
