  ('higher-math-board-mymensingh-2023-mcq-025', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p26', 'কোনো ত্রিভুজের লম্ববিন্দু থেকে কোনো শীর্ষের দূরত্ব 6 সে.মি. হলে পরিকেন্দ্র থেকে ঐ শীর্ষের বিপরীত বাহুর মধ্যবিন্দুর দূরত্ব কত?', 'mcq', '{"ক":"12 সে.মি.","খ":"9 সে.মি.","গ":"6 সে.মি.","ঘ":"3 সে.মি"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-mymensingh-2023-mcq', false, 'board-mcq', null, null, 'mymensingh', 2023, true),
