  ('higher-math-board-rajshahi-2024-mcq-014', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p18', 'β = 7π 2 i. cos(β − π 6 )= − 1 2 ii. co sce (β − π 3 )= −2 iii. tan (β − π 4 )= −1 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-017', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p18', 'sin θ = 5 13 এবং π < θ < 3π 2 হলে, cos θ = কত?', 'mcq', '{"ক":"13","খ":"12","গ":"− 12","ঘ":"− 13 12 13 13 12"}'::jsonb, 'গ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-018', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p19', '3y = 6x - 2 সরলরেখার - i. ঢাল 6 ii. y-অক্ষের ছেদক − 2 3 iii. x-অক্ষের ধনাত্মক দিকের সাথে উৎপন্ন কোণ সূক্ষ্মকোণ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-019', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p19', 'A (1, 3), B (3, 2) এবং C (-4, -2) শীর্ষবিশিষ্ট △ ABC এর ক্ষেত্রফল কত বর্গএকক?', 'mcq', '{"ক":"15 2 বর্গএকক","খ":"15 বর্গএকক","গ":"35 2 বর্গএকক","ঘ":"30 বর্গএকক"}'::jsonb, 'ক', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-020', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p19', 'চিত্রে X ও Y যথাক্রমে PQ ও SR এর মধ্যবিন্দু যেখানে PS|| QR এবং PS= 6cm, QR = 10 cm হলে, XY এর মান কত?', 'mcq', '{"ক":"16 cm","খ":"8cm","গ":"4cm","ঘ":"2 cm"}'::jsonb, 'খ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-021', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p20', 'একটি মুদ্রাকে তিনবার নিক্ষেপ করা হলে হেড অপেক্ষা অধিকবার টেল আসার সম্ভাবনা কত?', 'mcq', '{"ক":"2 3","খ":"1 2","গ":"1 8","ঘ":"1 6"}'::jsonb, 'খ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-022', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p20', '(2x 2 − 1 ) 10 এর বিস্তৃতিতে x বার্জিত পদটি কততম? 3 2x', 'mcq', '{"ক":"3 তম","খ":"4 তম","গ":"5 তম","ঘ":"6 তম"}'::jsonb, 'গ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-023', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p20', 'কিছু সংখ্যক লোকের মধ্যে 70 জন ফু টবল, 50 জন ক্রিকেট এবং 40 জন ফু টবল ও ক্রিকেট খেলা পছন্দ করে। দুইটি খেলার অন্তত একটি খেলা পছন্দ করে কত জন?', 'mcq', '{"ক":"70","খ":"90","গ":"120","ঘ":"160"}'::jsonb, 'খ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-rajshahi-2024-mcq-025', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p20', 'P (x) = 6x 5 + x 3 2 হলে, 2+12x i. বহুপদীটির মাত্রা 5 ii. বহুপদীটির মুখ্যসহগ 1 2 iii. P(-2)=2 নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'higher-math-board-rajshahi-2024-mcq', false, 'board-mcq', null, null, 'rajshahi', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-001', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p11', 'রেখাটি x অক্ষের ধনাত্মক দিকের সাথে কত কোণ উৎপন্ন করে?', 'mcq', '{"ক":"30°","খ":"60°","গ":"120°","ঘ":"150°"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, 'একটি সরলরেখার ঢাল এবং রেখাটি (-2, 0) বিন্দুগামী। − 1 √3', 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-003', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p11', 'সমস্যাটির অসমতা রূপ নিচের কোনটি?', 'mcq', '{"ক":"x+x+60 2 ≤ 50","খ":"2x + 3x +60 5 ≤ 50","গ":"x+x+60 5 ≥ 50","ঘ":"x+x+60 5 ≤ 50"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, 'একটি গাড়ি 2 ঘণ্টায় যায় x কি. মি. এবং ও ঘণ্টায় যায় (x + 60) কি. মি.। গাড়িটির গড় গতিবেগ অনূর্ধ্ব 50 কি. মি.।', 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-004', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p11', 'সমস্যাটিতে x এর সম্ভাব্য মান নিচের কোনটি?', 'mcq', '{"ক":"0","খ":"0","গ":"0 < x ≤155","ঘ":"0"}'::jsonb, 'ক', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, 'একটি গাড়ি 2 ঘণ্টায় যায় x কি. মি. এবং ও ঘণ্টায় যায় (x + 60) কি. মি.। গাড়িটির গড় গতিবেগ অনূর্ধ্ব 50 কি. মি.।', 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-005', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p11', '180元 মিটার পথ যেতে একটি চাকা 30 বার ঘোরে। চাকাটির ব্যাসার্ধ কত?', 'mcq', '{"ক":"2 মিটার","খ":"3 মিটার","গ":"4 মিটার","ঘ":"6 মিটার"}'::jsonb, 'খ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
