  ('higher-math-board-sylhet-2024-mcq-010', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', 'দুইটি ধনাত্মক সংখ্যার বর্গের সমষ্টি 170 এবং সংখ্যাদ্বয়ের গুণফল 77 হলে, ঐ সংখ্যাদ্বয়ের বর্গের অন্তর কত?', 'mcq', '{"ক":"18","খ":"51","গ":"72","ঘ":"85"}'::jsonb, 'গ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-011', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', '− → = m − → হলে- PQ RS i. PQ|| RS ii . − → ও − → সমমুখি হবে যখন m > 0 PQ RS iii. . − → ও −→ বিপরীতমুখী হবে যখন। m<0 PQ RS নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-012', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', 'একটি ছক্কা ও দুইটি মুদ্রা একত্রে একবার নিক্ষেপ করলে সংঘটিত ঘটনার নমুনা বিন্দুর সংখ্যা কত হবে?', 'mcq', '{"ক":"12","খ":"24","গ":"48","ঘ":"72"}'::jsonb, 'খ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
