  ('higher-math-board-sylhet-2024-mcq-014', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', 'সার্বিক সেট U= {3, 4, 5, 6}, হলে, S = {x: x+2 ≤ 7} এর প্রকৃ ত উপসেট কোনটি?', 'mcq', '{"ক":"{3,6}","খ":"{3, 5}","গ":"{3, 4, 5}","ঘ":"{3,5,6}"}'::jsonb, 'খ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-015', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', '3 সে. মি., 4 সে. মি. ও 5 সে. মি. বাহুবিশিষ্ট একটি ত্রিভুজের, মধ্যমাগুলোর উপর অঙ্কিত বর্গক্ষেত্রসমূহের ক্ষেত্রফলের সমষ্টি কত?', 'mcq', '{"ক":"37-5 বর্গ সে. মি.","খ":"50 বর্গ সে. মি.","গ":"75 বর্গ সে. মি.","ঘ":"112-5 বর্গ সে. মি."}'::jsonb, 'ক', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-016', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', '∫ (x) = 3x ফাংশনটির ডোমেন নিচের কোনটি? 3−x', 'mcq', '{"ক":"{x ∈ R : x>3}","খ":"{x ∈ R: x<3}","গ":"{x ∈ R : x≠3}","ঘ":"{x ∈ R : x≠0}"}'::jsonb, 'গ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
