  ('higher-math-board-sylhet-2024-mcq-020', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', '5x - 3 - x2 = 0 সমীকরণের মূলদ্বয় কীরূপ হবে?', 'mcq', '{"ক":"অবাস্তব","খ":"বাস্তব ও সমান","গ":"বাস্তব ও মূলদ","ঘ":"বাস্তব ও অমূলদ"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-021', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p12', 'একটি ঘনকের সম্পূর্ণ পৃষ্ঠের ক্ষেত্রফল 54 বর্গ সে. মি.। এর কর্ণের দৈর্ঘ্য কত?', 'mcq', '{"ক":"4-24 সে. মি.","খ":"5-20 সে. মি.","গ":"12-73 সে. মি.","ঘ":"15-59 সে. মি."}'::jsonb, 'খ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-022', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'একটি ত্রিভুজাকার প্রিজমের ভূমির বাহুগুলোর দৈর্ঘ্য যথাক্রমে 13 সে. মি., 12 সে. মি. ও 5 সে. মি. এবং উচ্চতা 15 সে. মি.। প্রিজমটির আয়তন কত?', 'mcq', '{"ক":"30 ঘন সে. মি.","খ":"60 ঘন সে. মি.","গ":"450 ঘন সে. মি.","ঘ":"510 ঘন সে. মি."}'::jsonb, 'গ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-023', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', '1 2 + 1 3 + 1 4 + . . . . . . . . . .. . . . . . .. ধারাটির অসীমতক সমষ্টি কত? 3 3 3', 'mcq', '{"ক":"5 2","খ":"3 2","গ":"1 2","ঘ":"1 6"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-024', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'কোনো ত্রিভুজের উচ্চতা h, ভূমির উপর মধ্যমা d এবং ভূমি সংলগ্ন একটি কোণ ∠x দেওয়া আছে। ত্রিভুজটি অঙ্কন করতে হলে- i. ভূমির উপর লম্ব অঙ্কন করতে হবে ii. x কে সমদ্বিখণ্ডিত করতে হবে ∠ iii. ভূমি থেকে d এর সমান অংশ কাটতে হবে নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i","খ":"ii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('higher-math-board-sylhet-2024-mcq-025', 'class9-higher-math-bn-guide', 'satt-higher-math-board.pdf p13', 'cos 5θ = sin 5θ হলে, θ এর মান কত?', 'mcq', '{"ক":"5π 4","খ":"π 2","গ":"π 5","ঘ":"π 20"}'::jsonb, 'ঘ', 1, false, 'higher-math-board-sylhet-2024-mcq', false, 'board-mcq', null, null, 'sylhet', 2024, true),
  ('ict-board-all-2017-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p52', 'ডাটাবেজ সফটওয়্যার চালু করার ধাপগুলো- i. Start মেনু হতে All program-এ ক্লিক ii. Microsoft Office-এ ক্লিক iii. Microsoft Access-এ ক্লিক নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, 'প্রধান শিক্ষক বিদ্যালয়ের আয়-ব্যয়, ছাত্র-ছাত্রীর তথ্যসহ অন্যান্য তথ্য কম্পিউটারে সংরক্ষণ করার জন্য অফিস সহকারীকে নির্দেশ প্রদান করলেন। তিনি কম্পিউটার শিক্ষকের সহায়তায় ডাটাবেজ সফটওয়্যার ব্যবহার শুরু করেন।', 'all', 2017, true),
  ('ict-board-all-2017-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', 'উদ্দীপকে ব্যবহৃত ডাটাবেজের মাধ্যমে সংরক্ষণ ও নিয়ন্ত্রণ করা যায়— i. বার্ষিক রিপোর্ট ii. প্রাপ্য ও প্রদেয় চাহিদা iii. তথ্য অনুসন্ধান নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, 'প্রধান শিক্ষক বিদ্যালয়ের আয়-ব্যয়, ছাত্র-ছাত্রীর তথ্যসহ অন্যান্য তথ্য কম্পিউটারে সংরক্ষণ করার জন্য অফিস সহকারীকে নির্দেশ প্রদান করলেন। তিনি কম্পিউটার শিক্ষকের সহায়তায় ডাটাবেজ সফটওয়্যার ব্যবহার শুরু করেন।', 'all', 2017, true),
  ('ict-board-all-2017-mcq-003', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', '''?'' চিহ্নিত F2 সেলে কত হবে?', 'mcq', '{"ক":"55.00","খ":"55.33","গ":"84.33","ঘ":"68.33"}'::jsonb, 'ক', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, 'A B C D E F 1 name Ban Eng Math Total Avarage 2 X 45 50 70 3 Y 65 60 80 4 Z 55 40 50', 'all', 2017, true),
  ('ict-board-all-2017-mcq-004', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', '''X'' এর Total number বের করতে সূত্র ব্যবহার করতে হবে— i. B2+C2+D2 ii. Sum (B2 + C2 + D2 ) iii. - Sum (B2 : D2 ) নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, 'A B C D E F 1 name Ban Eng Math Total Avarage 2 X 45 50 70 3 Y 65 60 80 4 Z 55 40 50', 'all', 2017, true),
  ('ict-board-all-2017-mcq-005', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', '''X'' কম্পিউটারের গতি বাড়ানোর জন্য ব্যবহার করবে- i. ডিস্ক ক্লিন আপ ii. ডিস্ক ডিফ্র্যাগমেন্টার iii. ডিস্ক রিমুভার নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, '''X'' কিছু দিন যাবৎ লক্ষ করছে, তার কম্পিউটার চালু হতে বেশি সময় লাগছে এবং মাঝে মাঝে। রি-বুট হয়ে সংরক্ষিত ফাইল হারিয়ে যাচ্ছে। এ সমস্যার কথা ম্যাডামকে বললে তিনি প্রতিরোধ সফটওয়্যার ব্যবহারের পরামর্শ দেন।', 'all', 2017, true),
  ('ict-board-all-2017-mcq-006', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', 'ম্যাডামের পরামর্শকৃ ত সফটওয়্যার হচ্ছে— i এন্টি-ভাইরাস ii. এন্টি-ক্লিন আপ iii. এন্টি-ম্যালওয়্যার নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i, ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, '''X'' কিছু দিন যাবৎ লক্ষ করছে, তার কম্পিউটার চালু হতে বেশি সময় লাগছে এবং মাঝে মাঝে। রি-বুট হয়ে সংরক্ষিত ফাইল হারিয়ে যাচ্ছে। এ সমস্যার কথা ম্যাডামকে বললে তিনি প্রতিরোধ সফটওয়্যার ব্যবহারের পরামর্শ দেন।', 'all', 2017, true),
  ('ict-board-all-2017-mcq-007', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', 'মাল্টিমিডিয়া সফটওয়্যার তৈরির প্রোগ্রাম কোনটি?', 'mcq', '{"ক":"প্রিমিয়ার","খ":"ফটোশপ","গ":"ফ্ল্যাশ","ঘ":"ডিরেক্টর"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, null, 'all', 2017, true),
  ('ict-board-all-2017-mcq-008', 'class9-ict-bn-guide', 'satt-ict-board.pdf p53', 'বাংলাদেশে ডাক বিভাগের MTS এর মাধ্যমে ১ মিনিটে কত টাকা পর্যন্ত পাঠানো যায়?', 'mcq', '{"ক":"৪০,০০০","খ":"৫০,০০০","গ":"৬০,০০০","ঘ":"৭০,০০০"}'::jsonb, 'খ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, null, 'all', 2017, true),
